<template>
	<template>
	  <nut-notify></nut-notify>
	</template>
	<scroll-view scroll-y style="height: 100vh;">
		<div class="box">
				<nut-cell @click="toAddAddress('start')" :title="'起点  '+submitForm.startAddress.title+' '+submitForm.startAddress.detail" :sub-title="submitForm.startAddress.name+' '+submitForm.startAddress.phone">
					<template #icon>
							<image class="nut-icon" src="/static/icons/start.png"></image>
					</template>
					<template #link>
						<nut-button @tap.stop="showStartAddresses" size="mini" type="primary">地址簿</nut-button>
					</template>
				</nut-cell>
				<nut-cell @click="toAddAddress('end')" :title="'终点  '+submitForm.endAddress.title+' '+submitForm.endAddress.detail" :sub-title="submitForm.endAddress.name+' '+submitForm.endAddress.phone">
					<template #icon>
						<image class="nut-icon" src="/static/icons/end.png"></image>
					</template>
					<template #link>
						<nut-button @tap.stop="showEndAddresses($event)" size="mini" type="primary">地址簿</nut-button>
					</template>
				</nut-cell>
				<nut-cell v-if="nearbyRiderInfo.text" title="附近骑手" :desc="nearbyRiderInfo.text"></nut-cell>
				<nut-cell @click="showDatePopupClick" is-link title="配送时间" :desc="specifiedTimeText">
					<!-- <template #icon>
						<image class="nut-icon" src="/static/logo.png"></image>
					</template> -->
				</nut-cell>
				<nut-cell @click="showGenderPopup = true" is-link title="性别限制" :desc="genderText">
					<!-- <template #icon>
						<image class="nut-icon" src="/static/logo.png"></image>
					</template> -->
				</nut-cell>
			</div>
			<div class="box">
				<nut-cell @click="showServiceTypePopup = true" is-link title="物品类型" :desc="submitForm.tag == '' ? '' : submitForm.tag+'-'+submitForm.weight">
					<template #icon>
						<image class="nut-icon" src="/static/icons/包裹.png"></image>
					</template>
				</nut-cell>
				<nut-cell @click="showServiceTypePopup = true" is-link title="计费重量" :desc="weightText"></nut-cell>
				<nut-cell @click="openVolumePopup" is-link title="物品尺寸" :desc="volumeSizeText"></nut-cell>
				<nut-cell @click="openInsuredPopup" is-link title="保价金额" :desc="insuredAmountText"></nut-cell>
				<div style="position: relative;">
					<nut-textarea placeholder="请输入详细描述" v-model="submitForm.detail" limit-show max-length="100" />
					<div @click="showImagePopup = true" class="myImage">
						<nut-icon name="/static/icons/添加图片.png"></nut-icon>
						<span style="height: 100%;vertical-align: middle;">补充物品图</span>
					</div>
				</div>
		
			</div>
			<div class="box">
		
				<nut-cell @click="showMoneyPopup = true" is-link title="追加金额" :desc="submitForm.additionalAmount">
					<template #icon>
						<image class="nut-icon" src="/static/icons/钱币.png"></image>
					</template>
				</nut-cell>
		<!-- 		<nut-cell is-link title="商品预估金额" desc="">
		
				</nut-cell> -->
		
			</div>
			<div class="box">
				<nut-cell @click="showCancelTimePopup = true" is-link title="自动取消" :desc="autoCancelText">
		
				</nut-cell>
				<nut-cell title="支付方式" desc="微信支付">
					<template #link>
						<image style="margin-left: 5px;" class="nut-icon" src="/static/icons/微信支付.png"></image>
					</template>
				</nut-cell>
			</div>

			<div class="box price-detail-box" v-if="hasPricingInfo">
				<div class="price-detail-header">
					<span class="price-detail-title">费用明细</span>
					<span v-if="routeInfo.distanceText" class="price-detail-route">{{routeInfo.distanceText}} · {{routeInfo.durationText}}</span>
				</div>
				<div class="price-weight-summary">
					<span>实际 {{formatKg(pricingInfo.actualWeightKg)}}kg</span>
					<span>体积 {{formatKg(pricingInfo.volumeWeightKg)}}kg</span>
					<span>计费 {{formatKg(pricingInfo.chargeWeightKg)}}kg</span>
				</div>
				<div v-for="(item,index) in priceItems" :key="index" class="price-detail-row">
					<div>
						<div class="price-detail-name">{{item.name}}</div>
						<div v-if="item.remark" class="price-detail-remark">{{item.remark}}</div>
					</div>
					<div class="price-detail-amount">¥{{formatAmount(item.amount)}}</div>
				</div>
				<div class="price-detail-total">
					<span>应付金额</span>
					<span>¥{{formatAmount(pricingInfo.payableAmount)}}</span>
				</div>
			</div>
			
			<div class="orderBtnBox">
				<view class="boxLeft">
					<span class="boxPrice">{{totalPrice}}</span>
					<span class="boxPrice" style="font-size: small;"> 元</span>
					<div v-if="routeInfo.distanceText" style="font-size: 12px;color: #666;">{{routeInfo.distanceText}} · {{routeInfo.durationText}}</div>
				</view>
				<div class="boxRight">
					<button :loading="btnSubmitLoading" type="primary" class="myBtn" @click="submitOrder">提交订单</button>
				</div>
			</div>
			
			<div class="box" style="height: 15%;background-color: transparent;box-shadow: none;">
				<div style="width: 100%;height: 20%;">
				</div>
			</div>
				
		
			<template>
				<nut-popup v-model:visible="showGenderPopup" position="bottom" safe-area-inset-bottom>
					<nut-picker :columns="genderData" title="性别限制" 
						@cancel="showGenderPopup = false" @confirm="onGenderConfirm">
					</nut-picker>
				</nut-popup>
				<nut-popup v-model:visible="showDatePopup" position="bottom" safe-area-inset-bottom>
					<nut-date-picker v-model="currentDate" :min-date="minDate" :max-date="maxDate" type="datetime"
						:minute-step="15" is-show-chinese @confirm="onTimedConfirm" ok-text="指定时间"
						@cancel="onTimedCancel" cancel-text="尽快配送">
					</nut-date-picker>
				</nut-popup>
				<nut-popup v-model:visible="showServiceTypePopup" position="bottom" safe-area-inset-bottom>
					<div class="nut-picker__bar">
						<div class="nut-picker__cancel nut-picker__left nut-picker__button">取消</div>
						<div class="nut-picker__title">物品类型</div>
						<div @click="confirmTag" class="nut-picker__confirm nut-picker__right nut-picker__button">确认</div>
					</div>
					<div class="custom-content">
						<nut-tag 
							v-for="(item, index) in tagList"
							:key="index" 
							custom-color="#fa2400" 
							@click="setActiveTag(index)"
							:plain="index === activeTagIndex ? false : true">{{item.name}}{{Number(item.sizeRequired) === 1 ? ' 需尺寸' : ''}}</nut-tag>
						
						<div v-show="tagRemark != ''" class="remark">{{tagRemark}}</div>
						<div v-if="selectedTagRequiresSize" class="remark required-size-tip">该类型属于大件或大体积物品，需要填写长、宽、高后才能下单。</div>
						<div v-show="activeTagIndex == tagList.length-1">
							<nut-input  v-model="submitForm.tag" placeholder="其它" max-length="8" show-word-limit></nut-input>
						</div>
						<div class="range-box">
							<div style="margin-bottom: 26px;" class="remark">
								<span style="font-weight: bold;color: black;">物品重量: </span>{{submitForm.weight}} (按实际情况填写)
							</div>
							<nut-range v-model="rangeValue" :max="20" :min="2" @change="onWeightChange" />
						</div>
					</div>
		
		
				</nut-popup>
				<nut-popup v-model:visible="showImagePopup" position="bottom" safe-area-inset-bottom>
					<div class="nut-picker__bar">
						<div class="nut-picker__title">附件图片</div>
					</div>
					<div class="custom-content">
						<nut-uploader @file-item-click="fileClick" @success="uploadSuccess" @delete="uploadDelete"
							@oversize="oversize" :headers="headers" :data="uploaderData" :maximize="5242880" name="file" maximum="5"
							:url="uploadUrl"></nut-uploader>
					</div>
				</nut-popup>
				<nut-popup v-model:visible="showMoneyPopup" position="bottom" safe-area-inset-bottom>
					<div class="nut-picker__bar">
						<div class="nut-picker__title">追加赏金可提高接单几率</div>
					</div>
					<div class="custom-content">
						<nut-input v-model="currAttachMoney" type="digit">
							<template #left>
								<nut-icon name="/static/icons/RMB.png"></nut-icon>
							</template>
		
							<template #right>
								<nut-button @click="onConfimAttachMoney" type="primary" size="small">确定追加</nut-button>
							</template>
		
						</nut-input>
					</div>
				</nut-popup>
				<nut-popup v-model:visible="showVolumePopup" position="bottom" safe-area-inset-bottom>
					<div class="nut-picker__bar">
						<div class="nut-picker__title">物品尺寸</div>
					</div>
					<div class="custom-content">
						<div class="volume-input-row">
							<nut-input v-model="currVolumeLengthCm" type="digit" placeholder="长(cm)"></nut-input>
							<nut-input v-model="currVolumeWidthCm" type="digit" placeholder="宽(cm)"></nut-input>
							<nut-input v-model="currVolumeHeightCm" type="digit" placeholder="高(cm)"></nut-input>
						</div>
						<div class="remark">用于计算体积重量，未填写时仅按实际重量计费</div>
						<nut-button @click="onConfirmVolume" block type="primary">保存尺寸</nut-button>
					</div>
				</nut-popup>
				<nut-popup v-model:visible="showInsuredPopup" position="bottom" safe-area-inset-bottom>
					<div class="nut-picker__bar">
						<div class="nut-picker__title">保价金额</div>
					</div>
					<div class="custom-content">
						<nut-input v-model="currInsuredAmount" type="digit" placeholder="不保价可填0">
							<template #left>
								<nut-icon name="/static/icons/RMB.png"></nut-icon>
							</template>
						</nut-input>
						<div class="remark">保价费由后端计费规则实时计算</div>
						<nut-button @click="onConfirmInsured" block type="primary">保存保价</nut-button>
					</div>
				</nut-popup>
				<nut-popup v-model:visible="showCancelTimePopup" position="bottom" safe-area-inset-bottom>
					<nut-picker  :columns="cancelTimes" title="未接单自动取消" @confirm="onConfirmCancelTime"
						@cancel="showCancelTimePopup = false">
					</nut-picker>
				</nut-popup>
				<nut-address
					v-model:visible="showStartAddressPopup" 
					type="exist" 
					:exist-address="startAddressList" 
					:is-show-custom-address="false" 
					@selected="selectedStartAddress" 
					exist-address-title="取货地址">
				</nut-address>
				<nut-address
					v-model:visible="showEndAddressPopup" 
					type="exist" 
					:exist-address="endAddressList" 
					:is-show-custom-address="false" 
					@selected="selectedEndAddress" 
					exist-address-title="送货地址">
				</nut-address>
			</template>
	</scroll-view>
	
</template>
<script setup>

</script>
<script>
	import {upload_url} from '@/request/request.js'
	import {
		toRaw
	} from "vue";
	import {
		postSubmitOrder,
		postRouteEstimate,
		postPricingEstimate,
		getNearbyRiderCount
	} from "@/request/apis/order.js"
	import {
		listSchool
	} from "@/request/apis/school.js"
	import {
		getListTag
	} from "@/request/apis/tag.js"
	import {
		getListAddress
	} from "@/request/apis/address.js"
	import {
		uploadFile
	} from '@/request/request.js'
	import { useNotify } from 'nutui-uniapp/composables';
	export default {
		setup() {
		   const notify = useNotify();
		   const showPrimary = (message) => {notify.primary(message);};
		   const showSuccess = (message) => {notify.success(message);};
		   const showDanger = (message) => {notify.danger(message);};
		   const showWarning = (message) => {notify.warning(message);};
		   const hideNotify = () => {notify.hide();};
		   return {showPrimary,showSuccess,showDanger,showWarning,hideNotify};
		 },
		data() {
			return {
				btnSubmitLoading:false,
				totalPrice:'--',
				routeInfo:{},
				pricingInfo:{},
				nearbyRiderInfo:{},
				uploadUrl:upload_url,
				specifiedTimeText:'尽快配送',
				genderText:'不限',
				uploaderData:{
					type:1,
					name:''
				},
				autoCancelText:'30分钟',
				currAttachMoney:0,
				currVolumeLengthCm:'',
				currVolumeWidthCm:'',
				currVolumeHeightCm:'',
				currInsuredAmount:0,
				activeTagIndex:-1,
				tagRemark:'',
				tagList:[
					{
						name:'其它',
						remark:''
					}
				],
				currSchool:null, //当前校区
				submitForm:{
					serviceType:0 , // 帮取送
					schoolId:null, // 学校id
					weight:'小于2KG',  // 物品重量
					detail:'',  // 订单详情
					tag:'',  // 物品类型
					isTimed:0, // 是否指定配送时间
					specifiedTime:null, // 具体指定配送时间
					autoCancelTtl:1800, // 付款未接单自动取消时间 秒
					gender:2, // 限制性别 2不限
					additionalAmount:0, // 追加金额
					volumeLengthCm:null,
					volumeWidthCm:null,
					volumeHeightCm:null,
					insuredAmount:0,
					estimatedPrice:0, //商品预估价格
					attachImages:[], // 附件图片的ossid
					attachFiles:[], // 附件文件的ossid
					startAddress:{
						id:'',
						name:'',
						phone:'',
						title:'',
						detail:'',
						lat:'',
						lon:''
					},
					endAddress:{
						id:'',
						name:'',
						phone:'',
						title:'',
						detail:'',
						lat:'',
						lon:''
					},
				},
				headers: {
					Authorization: 'Bearer ' + uni.getStorageSync("token"),
					'Content-Type': 'multipart/form-data',
				},
				ossList: [],
				showGenderPopup: false,
				showDatePopup: false,
				showServiceTypePopup: false,
				showImagePopup: false,
				showMoneyPopup: false,
				showVolumePopup: false,
				showInsuredPopup: false,
				showCancelTimePopup: false,
				showStartAddressPopup:false,
				showEndAddressPopup:false,
				genderData: [{
						text: "不限",
						value: 2
					},
					{
						text: "男",
						value: 1
					},
					{
						text: "女",
						value: 0
					}
				],
				minDate: new Date(2020, 0, 1),
				maxDate: new Date(2025, 10, 1),
				currentDate: new Date(2022, 4, 10, 10, 10),
				rangeValue: 2,
				cancelTimes: [{
						text: '30分钟',
						value: 1800
					},
					{
						text: '1小时',
						value: 3600
					},
					{
						text: '2小时',
						value: 7200
					},
					{
						text: '3小时',
						value: 10800
					},
					{
						text: '5小时',
						value: 18000
					},
					{
						text: '10小时',
						value: 36000
					},
					{
						text: '24小时',
						value: 86400
					},
					{
						text: '48小时',
						value: 172800
					}
				],
				startAddressList:[],
				endAddressList:[],
			}
		},
		onLoad(options) {
			//this.initDate()
			this.initData()
			this.applyHomePrefill(options)
			this.getAddresses()
			this.getTags()
			this.cacurlatePrice()
		},
		onReachBottom() {

		},
		computed: {
			hasPricingInfo() {
				return this.pricingInfo && this.pricingInfo.payableAmount != null
			},
			priceItems() {
				return Array.isArray(this.pricingInfo.items) ? this.pricingInfo.items : []
			},
			weightText() {
				return this.submitForm.weight || '默认1KG'
			},
			volumeSizeText() {
				const {volumeLengthCm, volumeWidthCm, volumeHeightCm} = this.submitForm
				if(!volumeLengthCm && !volumeWidthCm && !volumeHeightCm) return '未填写'
				return `${volumeLengthCm || '-'}×${volumeWidthCm || '-'}×${volumeHeightCm || '-'}cm`
			},
			insuredAmountText() {
				const amount = Number(this.submitForm.insuredAmount || 0)
				return amount > 0 ? `${amount.toFixed(2)}元` : '未保价'
			},
			selectedTagRequiresSize() {
				const item = this.tagList[this.activeTagIndex]
				return item && Number(item.sizeRequired) === 1
			}
		},
		methods: {
			applyHomePrefill(options = {}) {
				['startAddress', 'endAddress'].forEach(key => {
					if(!options[key]) return
					try {
						const address = JSON.parse(decodeURIComponent(options[key]))
						this.normalizeOrderAddress(address)
						this.submitForm[key] = {
							...this.submitForm[key],
							...address
						}
					} catch(e) {
						console.log(e)
					}
				})
				this.refreshRouteEstimate()
			},
			submitOrder() {
				let that = this
				let form = this.submitForm
				this.normalizeOrderAddress(form.startAddress)
				this.normalizeOrderAddress(form.endAddress)
				if(!this.validateItemSize()) return
				let ossIds = []
				let ossList = this.ossList
				for (var i = 0; i < ossList.length; i++) {
					ossIds.push(ossList[i].ossId)
				}
				form.attachImages = ossList
				this.btnSubmitLoading = true
				
				const SUBSCRIBE_ID = 'uQ8cRcy8jM8Rb09EUDZopOZgCLQcrxlFlGNzVez8_-w' // 模板ID
				if (wx.requestSubscribeMessage) {
				  wx.requestSubscribeMessage({
				    tmplIds: [SUBSCRIBE_ID],
				    complete() {
				    	postSubmitOrder(form).then(res => {
				    		console.log(res);
				    		uni.requestPayment({
				    			timeStamp: res.data.timeStamp, // 时间戳
				    			nonceStr: res.data.nonceStr, // 随机字符串
				    			package: res.data.packageValue,
				    			signType: res.data.signType, // 签名算法
				    			paySign: res.data.paySign, // 签名
				    			success: function (response) {
				    				console.log('支付成功',response);
				    				that.showSuccess("支付成功")
				    				setTimeout(() => {
				    					// 业务逻辑。。。
				    					uni.redirectTo({
				    						url:"/pages/API/order/detail/detail?id="+res.data.orderId
				    					})
				    				},1500)
				    			},
				    			fail: function (err) {
				    				console.log('支付失败',err);
				    				that.showDanger("支付失败")
				    				setTimeout(() => {
				    					// 业务逻辑。。。
				    					uni.redirectTo({
				    						url:"/pages/API/order/detail/detail?id="+res.data.orderId
				    					})
				    				},1500)
				    			},
				    			complete() {
				    				this.btnSubmitLoading = false
				    			}
				    		});
				    	}).catch(err => {
				    		that.showDanger(err)
				    	}).finally(res => {
				    		that.btnSubmitLoading = false
				    	})
				    }
				  });
				} else {
				  wx.showModal({
				    title: '提示',
				    content: '请更新您微信版本，来获取订阅消息功能',
				    showCancel: false
				  })
				}
				
				
				
				
			},
			cacurlatePrice() {
				this.normalizeOrderAddress(this.submitForm.startAddress)
				this.normalizeOrderAddress(this.submitForm.endAddress)
				if(!this.hasCoordinate(this.submitForm.startAddress) || !this.hasCoordinate(this.submitForm.endAddress)) {
					this.pricingInfo = {}
					this.totalPrice = '--'
					return
				}
				postPricingEstimate({
					schoolId:this.submitForm.schoolId,
					serviceType:this.submitForm.serviceType,
					weight:this.submitForm.weight,
					volumeLengthCm:this.submitForm.volumeLengthCm,
					volumeWidthCm:this.submitForm.volumeWidthCm,
					volumeHeightCm:this.submitForm.volumeHeightCm,
					insuredAmount:this.submitForm.insuredAmount,
					additionalAmount:this.submitForm.additionalAmount,
					startAddress:this.submitForm.startAddress,
					endAddress:this.submitForm.endAddress
				}).then(res => {
					const data = res.data || {}
					this.pricingInfo = data
					this.routeInfo = {
						distanceM:data.distanceM,
						durationSec:data.durationSec,
						distanceText:data.distanceText,
						durationText:data.durationText,
						provider:data.routeProvider,
						routeType:data.routeType,
						fallbackUsed:data.fallbackUsed
					}
					this.totalPrice = data.payableAmount == null ? '--' : Number(data.payableAmount).toFixed(2)
				}).catch(err => {
					this.pricingInfo = {}
					this.totalPrice = '--'
					this.showDanger(err || '计费失败')
				})
			},
			normalizeOrderAddress(address) {
				if(!address) return address
				if(!address.lng && address.lon) address.lng = address.lon
				if(!address.lon && address.lng) address.lon = address.lng
				return address
			},
			hasCoordinate(address) {
				return address && address.lat && (address.lng || address.lon)
			},
			getPickupAddress() {
				return this.submitForm.startAddress
			},
			refreshNearbyRiderCount() {
				const pickupAddress = this.getPickupAddress()
				this.normalizeOrderAddress(pickupAddress)
				if(!this.hasCoordinate(pickupAddress)) {
					this.nearbyRiderInfo = {}
					return
				}
				getNearbyRiderCount({
					lng: pickupAddress.lng || pickupAddress.lon,
					lat: pickupAddress.lat
				}).then(res => {
					const data = res.data || {}
					const count = data.nearbyRiderCount || 0
					this.nearbyRiderInfo = {
						count,
						text: count > 0 ? `附近约${count}名骑手可接单` : '附近骑手较少，接单可能变慢'
					}
				}).catch(() => {
					this.nearbyRiderInfo = {}
				})
			},
			refreshRouteEstimate() {
				this.normalizeOrderAddress(this.submitForm.startAddress)
				this.normalizeOrderAddress(this.submitForm.endAddress)
				this.refreshNearbyRiderCount()
				if(!this.hasCoordinate(this.submitForm.startAddress) || !this.hasCoordinate(this.submitForm.endAddress)) {
					this.routeInfo = {}
					return
				}
				postRouteEstimate({
					startAddress:this.submitForm.startAddress,
					endAddress:this.submitForm.endAddress
				}).then(res => {
					this.routeInfo = res.data || {}
					this.cacurlatePrice()
				}).catch(() => {
					this.routeInfo = {}
					this.cacurlatePrice()
				})
			},
			onGenderConfirm(e) {
				let item = e.selectedOptions[0]
				this.submitForm.gender = item.value
				this.genderText = item.text
				this.showGenderPopup = false
			},
			onConfirmCancelTime(e) {
				let item = e.selectedOptions[0]
				this.submitForm.autoCancelTtl = item.value
				this.autoCancelText = item.text
				this.showCancelTimePopup = false

			},
			formatAmount(value) {
				const amount = Number(value || 0)
				return Number.isNaN(amount) ? '0.00' : amount.toFixed(2)
			},
			formatKg(value) {
				const amount = Number(value || 0)
				return Number.isNaN(amount) ? '0.00' : amount.toFixed(2)
			},
			normalizeDecimal(value) {
				value = String(value == null ? '' : value)
				value = value.replace(/[^\d.]/g, '')
				value = value.replace(/\.{2,}/g, '.')
				value = value.replace(/^(\d*\.?)|(\d*)\.?/g, '$1$2')
				if (value.includes('.')) {
					const parts = value.split('.')
					value = `${parts[0]}.${parts[1].substring(0, 2)}`
				}
				value = value.replace(/^0+(\d)/, '$1')
				if (value.startsWith('.')) value = '0' + value
				return value
			},
			toNullableNumber(value) {
				const normalized = this.normalizeDecimal(value)
				return normalized === '' ? null : Number(normalized)
			},
			hasAnyVolume() {
				return Number(this.submitForm.volumeLengthCm || 0) > 0
					|| Number(this.submitForm.volumeWidthCm || 0) > 0
					|| Number(this.submitForm.volumeHeightCm || 0) > 0
			},
			hasCompleteVolume() {
				return Number(this.submitForm.volumeLengthCm || 0) > 0
					&& Number(this.submitForm.volumeWidthCm || 0) > 0
					&& Number(this.submitForm.volumeHeightCm || 0) > 0
			},
			requiresVolumeByTag(tagName = this.submitForm.tag) {
				const item = this.tagList.find(tag => tag.name === tagName)
				return item && Number(item.sizeRequired) === 1
			},
			validateItemSize() {
				if(this.hasAnyVolume() && !this.hasCompleteVolume()) {
					this.showWarning('物品尺寸需要完整填写长、宽、高')
					this.openVolumePopup()
					return false
				}
				if(this.requiresVolumeByTag() && !this.hasCompleteVolume()) {
					this.showWarning('该物品类型需要填写长、宽、高')
					this.openVolumePopup()
					return false
				}
				return true
			},
			openVolumePopup() {
				this.currVolumeLengthCm = this.submitForm.volumeLengthCm || ''
				this.currVolumeWidthCm = this.submitForm.volumeWidthCm || ''
				this.currVolumeHeightCm = this.submitForm.volumeHeightCm || ''
				this.showVolumePopup = true
			},
			openInsuredPopup() {
				this.currInsuredAmount = this.submitForm.insuredAmount || 0
				this.showInsuredPopup = true
			},
			onConfirmVolume() {
				this.submitForm.volumeLengthCm = this.toNullableNumber(this.currVolumeLengthCm)
				this.submitForm.volumeWidthCm = this.toNullableNumber(this.currVolumeWidthCm)
				this.submitForm.volumeHeightCm = this.toNullableNumber(this.currVolumeHeightCm)
				this.showVolumePopup = false
				this.cacurlatePrice()
			},
			onConfirmInsured() {
				const value = this.normalizeDecimal(this.currInsuredAmount)
				this.submitForm.insuredAmount = value === '' ? 0 : Number(value)
				this.currInsuredAmount = this.submitForm.insuredAmount
				this.showInsuredPopup = false
				this.cacurlatePrice()
			},
			onConfimAttachMoney() {
				let value = this.currAttachMoney;
				
				value = this.normalizeDecimal(value)
				
				console.log(value);
				// 更新格式化后的值
				this.submitForm.additionalAmount = value;
				this.currAttachMoney = value
				this.cacurlatePrice()
				
				this.showMoneyPopup = false
				
			},
			onTimedConfirm(e) {
				console.log(e);
				let day = e.selectedOptions[2].value
				let hour = e.selectedOptions[3].value
				let minute = e.selectedOptions[4].value
				
				this.submitForm.isTimed = 1
				this.submitForm.specifiedTime = this.parseLocalDateTime(this.currentDate)
				this.specifiedTimeText = day+'日 '+hour+':'+minute
				this.showDatePopup = false
			},
			parseLocalDateTime(date) {
				const localDateTime = date.getFullYear() + "-" +
				    String(date.getMonth() + 1).padStart(2, '0') + "-" +
				    String(date.getDate()).padStart(2, '0') + " " +
				    String(date.getHours()).padStart(2, '0') + ":" +
				    String(date.getMinutes()).padStart(2, '0') + ":" +
				    String(date.getSeconds()).padStart(2, '0');
				return localDateTime
			},
			onTimedCancel() {
				this.submitForm.isTimed = 0
				this.submitForm.specifiedTime = null
				this.specifiedTimeText = '尽快配送'
				this.showDatePopup = false
			},
			confirmTag() {
				if(this.activeTagIndex < 0) {
					this.showServiceTypePopup = false
					this.cacurlatePrice()
					return
				}
				if(this.activeTagIndex == this.tagList.length - 1 && this.submitForm.tag =='') {
					this.showWarning('请先输入物品类型')
					return
				}
				if(this.activeTagIndex != this.tagList.length - 1) {
					const selectedTag = this.tagList[this.activeTagIndex]
					this.submitForm.tag = selectedTag.name
				}
				this.showServiceTypePopup = false
				if(this.requiresVolumeByTag() && !this.hasCompleteVolume()) {
					this.showWarning('该物品类型需要填写尺寸')
					this.openVolumePopup()
					return
				}
				this.cacurlatePrice()
			},
			setActiveTag(index) {
			      this.activeTagIndex = index; // 设置当前点击的索引
				  this.tagRemark = this.tagList[index].remark
			},
			initData(){
				this.currSchool = this.$store.state.currSchool;
				this.submitForm.schoolId = this.currSchool.id
			},
			updateAddress(data,type) {
				if(type == 'start') {
					this.submitForm.startAddress = data
				}
				else if(type == 'end') {
					this.submitForm.endAddress = data
				}
				this.refreshRouteEstimate()
			},
			showStartAddresses(){
				this.showStartAddressPopup = true;
			},
			showEndAddresses(){
				this.showEndAddressPopup = true;
			},
			toAddAddress(type) {
				let data = null
				if(type == 'start') {
					data = JSON.stringify(this.submitForm.startAddress)
				}
				else {
					data = JSON.stringify(this.submitForm.endAddress)
				}
				uni.navigateTo({
					url:'/pages/API/address/add/add?data=' + data + '&type=' + type
				})
			},
			selectedStartAddress(prevExistAdd,nowExistAdd,arr) {
				if(nowExistAdd.provinceName + nowExistAdd.addressDetail == this.submitForm.endAddress.title + '-' +  this.submitForm.endAddress.detail) {
					this.showWarning('取送地址不能相同')
					return
				}
				this.submitForm.startAddress = {
					id:nowExistAdd.id,
					name:nowExistAdd.name,
					phone:nowExistAdd.phone,
					title:nowExistAdd.provinceName,
					detail:nowExistAdd.addressDetail.startsWith('-') ? nowExistAdd.addressDetail.slice(1) : nowExistAdd.addressDetail,
					lat:nowExistAdd.lat,
					lon:nowExistAdd.lon,
					lng:nowExistAdd.lon
				}
				this.refreshRouteEstimate()
				
			},
			selectedEndAddress(prevExistAdd,nowExistAdd,arr) {
				if(nowExistAdd.provinceName + nowExistAdd.addressDetail == this.submitForm.startAddress.title + '-' +  this.submitForm.startAddress.detail) {
					this.showWarning('取送地址不能相同')
					return
				}
				this.submitForm.endAddress = {
					name:nowExistAdd.name,
					phone:nowExistAdd.phone,
					title:nowExistAdd.provinceName,
					detail:nowExistAdd.addressDetail.startsWith('-') ? nowExistAdd.addressDetail.slice(1) : nowExistAdd.addressDetail,
					lat:nowExistAdd.lat,
					lon:nowExistAdd.lon,
					lng:nowExistAdd.lon
				}
				this.refreshRouteEstimate()
				
			},
			getTags(){
				getListTag({
					schoolId:this.currSchool.id,
					serviceType:this.submitForm.serviceType
				}).then(res => {
					console.log(res);
					this.tagList.unshift(...res.data)
				}).catch(err => {
					this.showWarning(err)
				})
			},
			getAddresses() {
				getListAddress({pageNum:1,pageSize:20}).then(res => {
					console.log(res);
					let rows = res.data
					this.startAddressList = this.mapFields(rows)
					this.endAddressList = this.mapFields(rows)
				}).catch(err => {
					this.showWarning(err)
				})
			},
			fileClick(file) {
				file = file.fileItem
				console.log(file);
				let imgsArray = [];
				imgsArray[0] = file.url;
				uni.previewImage({
					current: 0,
					urls: imgsArray
				});
			},
			oversize(files) {
				console.log(files);
				this.showWarning('文件大小超出5MB')
			},
			uploadDelete(e) {
				let index = e.index
				this.ossList.splice(index, 1)
			},
			uploadSuccess(e) {
				let data = e.data.data
				data = JSON.parse(data)
				let ossId = data.data.ossId
				this.ossList.push(ossId)
			},
			onWeightChange(e) {
				console.log(e);
				if (e == 2) {
					this.submitForm.weight = '小于2KG'
				} else if (e == 20) {
					this.submitForm.weight = '大于20KG'
				} else {
					this.submitForm.weight = e + 'KG左右'
				}
				this.cacurlatePrice()
			},
			showDatePopupClick() {
				this.initDate();
				this.showDatePopup = true
			},
			initDate() {
				const now = new Date();
				// 获取当前分钟数
				const currentMinutes = now.getMinutes();
				// 向上取整到最近的 15 的倍数
				const roundedMinutes = Math.ceil(currentMinutes / 15) * 15;
				// 如果超出 60 分钟，处理进位
				if (roundedMinutes >= 60) {
					now.setHours(now.getHours() + 1);
					now.setMinutes(0); // 分钟归零
				} else {
					now.setMinutes(roundedMinutes); // 设置为向上取整的分钟数
				}

				this.currentDate = now; // 当前时间
				this.minDate = now;
				// 设置最大时间为当前时间 + 7天
				const max = new Date();
				max.setDate(max.getDate() + 7); // 当前时间加7天
				this.maxDate = max;
			},
			mapFields(data) {
				 return data.map((formData) => ({
				    id: formData.id,
				    addressDetail: '-' + formData.detail,
				    cityName: '', // 默认值为空
				    countyName: '', // 默认值为空
				    provinceName: formData.title,
				    selectedAddress: false, 
				    townName: '', // 默认值为空
				    name: formData.name,
				    phone: formData.phone,
					lat:formData.lat,
					lon:formData.lon,
				  }));
			},
		},

	}
</script>

